--- index.html
+++ index.html
@@ -64,8 +64,8 @@
 let battleMoveMenu=false;
 function handleBattleKey(k){if(k==='Escape'){if(battleMoveMenu){battleMoveMenu=false;battleStep=0;battleMsg=`What will SPROUT do?`};return}if(k==='Enter'){if(!battleMoveMenu){if(battleStep===0){battleMoveMenu=true;battleMsg='Leaf Lash   |   Quick Bite   |   Guard'}else if(battleStep===1){battleMsg='1) Leaf Lash  2) Quick Bite  3) Guard'};return}attack(0)}if(k==='ArrowRight'||k==='ArrowLeft'||k==='ArrowDown'||k==='ArrowUp'){battleStep=(battleStep+1)%4}}
 function attack(){let damage=7+Math.floor(Math.random()*6);wildHP-=damage;if(wildHP<=0){battleMoveMenu=false;coins+=25;battleMsg=`${wild.name} fainted! You won 25 coins.`;setTimeout(()=>{scene='world';partyHP=Math.max(1,partyHP)},900);return}battleMsg=`Sprout used Leaf Lash! ${damage} damage!`;battleMoveMenu=false;battleStep=0;setTimeout(()=>{if(scene==='battle')enemyTurn()},700)}
 function enemyTurn(){let damage=4+Math.floor(Math.random()*5);partyHP-=damage;if(partyHP<=0){battleMsg='Sprout retreated. It is back in town!';setTimeout(()=>{partyHP=partyMax;player.x=8*32+16;player.y=10*32+16;scene='world'},900)}else battleMsg=`${wild.name} struck back for ${damage}!`}
-window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','Enter'].includes(e.key))e.prevent.preventDefault();keys[e.key]=true;if(scene==='world'&&(e.key==='Enter'||e.key===' '))interact();if(scene==='battle')handleBattleKey(e.key);});
+window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','Enter'].includes(e.key))e.preventDefault();keys[e.key]=true;if(scene==='world'&&(e.key==='Enter'||e.key===' '))interact();if(scene==='battle')handleBattleKey(e.key);});
 window.addEventListener('keyup',e=>keys[e.key]=false);document.querySelectorAll('[data-key]').forEach(b=>{let k=b.dataset.key;let go=e=>{e.preventDefault();keys[k]=true;if(k==='Enter'||k==='Escape'){if(scene==='world'&&k==='Enter')interact();if(scene==='battle')handleBattleKey(k)}};let stop=e=>{e.preventDefault();keys[k]=false};b.addEventListener('pointerdown',go);b.addEventListener('pointerup',stop);b.addEventListener('pointercancel',stop)});
 function loop(){tick++;if(scene==='world'){move();drawWorld();if(toastT>0)toastT--}else drawBattle();requestAnimationFrame(loop)}loop();
 </script></body></html>
